package com.v2ray.ang.fmt

import com.google.gson.JsonObject
import com.google.gson.JsonParser
import com.v2ray.ang.dto.entities.ProfileItem
import com.v2ray.ang.enums.EConfigType

/**
 * Parses a raw Xray JSON subscription (as generated by Remnawave) into VLESS
 * [ProfileItem]s — one per outbound (location). The subscription is a full Xray config
 * with `inbounds`, `outbounds`, `routing` and `dns`; this extracts the VLESS outbounds
 * so the client can pick a location.
 */
object XrayJsonFmt {

    /** True when [text] looks like a raw Xray JSON config rather than a list of share links. */
    fun looksLikeXrayJson(text: String): Boolean {
        val trimmed = text.trim()
        return trimmed.startsWith("{") &&
            trimmed.contains("\"outbounds\"") &&
            trimmed.contains("\"routing\"")
    }

    /**
     * Extracts VLESS outbounds from an Xray JSON subscription.
     *
     * @param json the raw subscription JSON.
     * @return one profile per VLESS outbound.
     */
    fun parseXrayJsonSubscription(json: String): List<ProfileItem> {
        val root = runCatching { JsonParser.parseString(json).asJsonObject }.getOrNull()
            ?: return emptyList()
        val outbounds = runCatching { root.getAsJsonArray("outbounds") }.getOrNull()
            ?: return emptyList()

        val profiles = mutableListOf<ProfileItem>()
        for (element in outbounds) {
            val outbound = runCatching { element.asJsonObject }.getOrNull() ?: continue
            val protocol = outbound.get("protocol")?.takeIf { !it.isJsonNull }?.asString
            if (protocol != "vless") continue

            parseVlessOutbound(outbound)?.let(profiles::add)
        }
        return profiles
    }

    private fun parseVlessOutbound(outbound: JsonObject): ProfileItem? {
        val settings = outbound.getAsJsonObject("settings") ?: return null
        val vnext = settings.getAsJsonArray("vnext") ?: return null
        val first = vnext.firstOrNull()?.asJsonObject ?: return null
        val user = first.getAsJsonArray("users")?.firstOrNull()?.asJsonObject

        val config = ProfileItem.create(EConfigType.VLESS)
        config.remarks = outbound.get("tag")?.takeIf { !it.isJsonNull }?.asString ?: "server"
        config.server = first.get("address")?.takeIf { !it.isJsonNull }?.asString
        config.serverPort = first.get("port")?.takeIf { !it.isJsonNull }?.asString
        config.password = user?.get("id")?.takeIf { !it.isJsonNull }?.asString
        config.method = user?.get("encryption")?.takeIf { !it.isJsonNull }?.asString ?: "none"
        config.flow = user?.get("flow")?.takeIf { !it.isJsonNull }?.asString

        val streamSettings = outbound.getAsJsonObject("streamSettings")
        config.network = streamSettings?.get("network")?.takeIf { !it.isJsonNull }?.asString ?: "tcp"
        config.security = streamSettings?.get("security")?.takeIf { !it.isJsonNull }?.asString

        val tls = streamSettings?.getAsJsonObject("tlsSettings")
        val reality = streamSettings?.getAsJsonObject("realitySettings")
        config.sni = (tls?.get("serverName") ?: reality?.get("serverName"))
            ?.takeIf { !it.isJsonNull }?.asString
        config.fingerPrint = tls?.get("fingerprint")?.takeIf { !it.isJsonNull }?.asString
        config.alpn = tls?.getAsJsonArray("alpn")
            ?.mapNotNull { it.takeIf { el -> !el.isJsonNull }?.asString }
            ?.joinToString(",")
            ?.takeIf { it.isNotEmpty() }
        config.insecure = tls?.get("allowInsecure")?.takeIf { !it.isJsonNull }?.asBoolean ?: false
        config.publicKey = reality?.get("publicKey")?.takeIf { !it.isJsonNull }?.asString
        config.shortId = reality?.get("shortId")?.takeIf { !it.isJsonNull }?.asString
        config.spiderX = reality?.get("spiderX")?.takeIf { !it.isJsonNull }?.asString

        val xhttp = streamSettings?.getAsJsonObject("xhttpSettings")
        config.host = xhttp?.get("host")?.takeIf { !it.isJsonNull }?.asString
        config.path = xhttp?.get("path")?.takeIf { !it.isJsonNull }?.asString
        config.xhttpMode = xhttp?.get("mode")?.takeIf { !it.isJsonNull }?.asString

        return config
    }
}
